                v: v,
                messageType: type,
                connectionEpoch: try string("connection_epoch"),
                sessionId: try c.decodeIfPresent(String.self, forKey: AnyCodingKey("session_id")),
                targetId: try string("target_id"),
                targetGeneration: try string("target_generation"),
                capabilityRevision: revision,
                grantEpoch: try string("grant_epoch"),
                actions: actions
            ))
        case "action.invoke":
            guard let v = try c.decodeIfPresent(UInt16.self, forKey: AnyCodingKey("v")),
                  let revision = try c.decodeIfPresent(UInt64.self, forKey: AnyCodingKey("capability_revision")),
                  let schemaVersion = try c.decodeIfPresent(UInt16.self, forKey: AnyCodingKey("schema_version")),
                  let parameters = try c.decodeIfPresent([String: JSONValue].self, forKey: AnyCodingKey("parameters"))
            else { throw WireError.invalidField("action request") }
            self = .actionInvoke(ActionRequestPayload(
                v: v,
                messageType: type,
                id: try string("id"),
                connectionEpoch: try string("connection_epoch"),
                sessionId: try c.decodeIfPresent(String.self, forKey: AnyCodingKey("session_id")),
                grantEpoch: try string("grant_epoch"),
                targetId: try string("target_id"),
                targetGeneration: try string("target_generation"),
                capabilityRevision: revision,
                action: try string("action"),
                schemaVersion: schemaVersion,
                parameters: parameters
            ))
        case "action.result":
            guard let v = try c.decodeIfPresent(UInt16.self, forKey: AnyCodingKey("v")),
                  let status = try c.decodeIfPresent(ActionStatus.self, forKey: AnyCodingKey("status"))
            else { throw WireError.invalidField("action result") }
            self = .actionResult(ActionResultPayload(
                v: v,
                messageType: type,
                id: try string("id"),
                connectionEpoch: try string("connection_epoch"),
                sessionId: try c.decodeIfPresent(String.self, forKey: AnyCodingKey("session_id")),
                status: status,
                errorCode: try c.decodeIfPresent(ActionErrorCode.self, forKey: AnyCodingKey("error_code")),
                state: try c.decodeIfPresent(JSONValue.self, forKey: AnyCodingKey("state")),
                capabilityRevision: try c.decodeIfPresent(UInt64.self, forKey: AnyCodingKey("capability_revision"))
            ))
        case "catalog.snapshot":
            self = .catalogSnapshot(try CatalogSnapshot(from: c))
        case "catalog.request":
            self = .catalogRequest(sessionID: try string("session_id"))
        case "stream.select":
            guard let target = try c.decodeIfPresent(StreamTarget.self, forKey: AnyCodingKey("target")) else {
                throw WireError.invalidField("stream target")
            }
            self = .streamSelect(sessionID: try string("session_id"), target: target)
        case "stream.stop":
            self = .streamStop(sessionID: try string("session_id"))
        case "stream.started":
            guard let target = try c.decodeIfPresent(StreamTarget.self, forKey: AnyCodingKey("target")),
                  let width = try c.decodeIfPresent(UInt32.self, forKey: AnyCodingKey("width")),
                  let height = try c.decodeIfPresent(UInt32.self, forKey: AnyCodingKey("height")),
                  let geometryEpoch = try c.decodeIfPresent(UInt64.self, forKey: AnyCodingKey("geometry_epoch"))
            else { throw WireError.invalidField("stream.started") }
            self = .streamStarted(
                sessionID: try string("session_id"),
                target: target,
                width: width,
                height: height,
                geometryEpoch: geometryEpoch,
                encoder: try string("encoder")
            )
        case "stream.stopped":
            self = .streamStopped(sessionID: try string("session_id"), reason: try string("reason"))
        case "stream.error":
            self = .streamError(
                sessionID: try string("session_id"),
                code: try string("code"),
                message: try string("message")
            )
        case "input.event":
            guard let event = try c.decodeIfPresent(PortableInputEvent.self, forKey: AnyCodingKey("event")) else {
                throw WireError.invalidField("input event")
            }
            self = .inputEvent(sessionID: try string("session_id"), event: event)
        default:
            throw WireError.unknownMessageType(type)
        }
    }

    func encodePayload(to container: inout KeyedEncodingContainer<AnyCodingKey>) throws {
        try container.encode(typeName, forKey: AnyCodingKey("type"))
        switch self {
        case let .clientHello(versions, clientID, clientNonce):
            try container.encode(versions, forKey: AnyCodingKey("versions"))
            try container.encode(clientID, forKey: AnyCodingKey("client_id"))
            try container.encode(clientNonce, forKey: AnyCodingKey("client_nonce"))
        case let .serverHello(selected, hostID, hostName, hostNonce, pairingID, expiresAt, policy):
            try container.encode(selected, forKey: AnyCodingKey("selected"))
            try container.encode(hostID, forKey: AnyCodingKey("host_id"))
            try container.encode(hostName, forKey: AnyCodingKey("host_name"))
            try container.encode(hostNonce, forKey: AnyCodingKey("host_nonce"))
            try container.encode(pairingID, forKey: AnyCodingKey("pairing_id"))
            try container.encode(expiresAt, forKey: AnyCodingKey("expires_at"))
            try container.encode(policy, forKey: AnyCodingKey("policy"))
        case let .pairingRequest(pairingID, tag):
            try container.encode(pairingID, forKey: AnyCodingKey("pairing_id"))
            try container.encode(tag, forKey: AnyCodingKey("tag"))
        case let .pairingAccepted(tag, sessionID, permissions):
            try container.encode(tag, forKey: AnyCodingKey("tag"))
            try container.encode(sessionID, forKey: AnyCodingKey("session_id"))
            try container.encode(permissions, forKey: AnyCodingKey("permissions"))
        case let .pairingRejected(reason):
            try container.encode(reason, forKey: AnyCodingKey("reason"))
        case let .sessionOpen(sessionID, permissions), let .sessionOpened(sessionID, permissions):
            try container.encode(sessionID, forKey: AnyCodingKey("session_id"))
            try container.encode(permissions, forKey: AnyCodingKey("permissions"))
        case let .mediaOffer(offer):
            try container.encode(offer.v, forKey: AnyCodingKey("v"))
            try container.encode(offer.port, forKey: AnyCodingKey("port"))
            try container.encode(offer.pairingID, forKey: AnyCodingKey("pairing_id"))
            try container.encode(offer.expiresAt, forKey: AnyCodingKey("expires_at"))
        case let .keyframeRequest(sessionID):
            try container.encode(sessionID, forKey: AnyCodingKey("session_id"))
        case let .ping(nonce), let .pong(nonce):
            try container.encode(nonce, forKey: AnyCodingKey("nonce"))
        case let .sessionClose(sessionID, reason):
            try container.encodeIfPresent(sessionID, forKey: AnyCodingKey("session_id"))
            try container.encode(reason, forKey: AnyCodingKey("reason"))
        case let .error(code, message):
            try container.encode(code, forKey: AnyCodingKey("code"))
            try container.encode(message, forKey: AnyCodingKey("message"))
        case let .capabilitySnapshot(snapshot):
            try snapshot.encodePayload(to: &container)
        case let .actionInvoke(request):
            try request.encodePayload(to: &container)
        case let .actionResult(result):
            try result.encodePayload(to: &container)
        case let .catalogSnapshot(snapshot):
            try snapshot.encodePayload(to: &container)
        case let .catalogRequest(sessionID):
            try container.encode(1, forKey: AnyCodingKey("v"))
            try container.encode(sessionID, forKey: AnyCodingKey("session_id"))
        case let .streamSelect(sessionID, target):
            try container.encode(1, forKey: AnyCodingKey("v"))
            try container.encode(sessionID, forKey: AnyCodingKey("session_id"))
            try container.encode(target, forKey: AnyCodingKey("target"))
        case let .streamStop(sessionID):
            try container.encode(1, forKey: AnyCodingKey("v"))
            try container.encode(sessionID, forKey: AnyCodingKey("session_id"))
        case let .streamStarted(sessionID, target, width, height, geometryEpoch, encoder):
            try container.encode(1, forKey: AnyCodingKey("v"))
            try container.encode(sessionID, forKey: AnyCodingKey("session_id"))
            try container.encode(target, forKey: AnyCodingKey("target"))
            try container.encode(width, forKey: AnyCodingKey("width"))
            try container.encode(height, forKey: AnyCodingKey("height"))
            try container.encode(geometryEpoch, forKey: AnyCodingKey("geometry_epoch"))
            try container.encode(encoder, forKey: AnyCodingKey("encoder"))
        case let .streamStopped(sessionID, reason):
            try container.encode(1, forKey: AnyCodingKey("v"))
            try container.encode(sessionID, forKey: AnyCodingKey("session_id"))
            try container.encode(reason, forKey: AnyCodingKey("reason"))
        case let .streamError(sessionID, code, message):
            try container.encode(1, forKey: AnyCodingKey("v"))
            try container.encode(sessionID, forKey: AnyCodingKey("session_id"))
            try container.encode(code, forKey: AnyCodingKey("code"))
            try container.encode(message, forKey: AnyCodingKey("message"))
        case let .inputEvent(sessionID, event):
            try container.encode(1, forKey: AnyCodingKey("v"))
            try container.encode(sessionID, forKey: AnyCodingKey("session_id"))
            try container.encode(event, forKey: AnyCodingKey("event"))
        }
    }

}

public enum WireError: Error, Equatable, CustomStringConvertible, LocalizedError {
    case frameTooLarge
    case frameTruncated
    case frameLengthMismatch
    case malformedJSON
    case unknownMessageType(String)
    case invalidField(String)
    case unexpectedMessage(String)
    case invalidTransition(String)
    case invalidIdentifier
    case invalidNonce
    case unsupportedVersion
    case expiredOffer
    case unknownPairing
    case authenticationFailed
    case sessionMismatch
    case permissionDenied
    case entropyUnavailable

    public var description: String {
        switch self {
        case .frameTooLarge: "control frame exceeds the size limit"
        case .frameTruncated: "control frame is truncated"
        case .frameLengthMismatch: "control frame length does not match"
        case .malformedJSON: "control frame is not valid JSON"
        case let .unknownMessageType(type): "unknown control message type \(type)"
        case let .invalidField(field): "missing or invalid field \(field)"
        case let .unexpectedMessage(type): "unexpected message \(type)"
        case let .invalidTransition(detail): "invalid transition: \(detail)"
        case .invalidIdentifier: "invalid identifier"
        case .invalidNonce: "invalid nonce or pairing identifier"
        case .unsupportedVersion: "no supported protocol version overlap"
        case .expiredOffer: "pairing offer expired"
        case .unknownPairing: "unknown pairing identifier"
        case .authenticationFailed: "pairing authentication failed"
        case .sessionMismatch: "session identifier does not match"
        case .permissionDenied: "permission request exceeds the grant"
        case .entropyUnavailable: "secure randomness is unavailable"
        }
    }

    public var errorDescription: String? { description }
}

public enum ControlFraming {
    public static let maxFrameBytes = 64 * 1024

    public static func encode(_ envelope: Envelope) throws -> Data {
        let json = try JSONEncoder().encode(envelope)
        guard json.count <= maxFrameBytes else { throw WireError.frameTooLarge }
        var data = Data()
        var length = UInt32(json.count).bigEndian
        withUnsafeBytes(of: &length) { data.append(contentsOf: $0) }
        data.append(json)
        return data
    }

    public static func decode(_ data: Data) throws -> Envelope {
        guard data.count >= 4 else { throw WireError.frameTruncated }
        let length = data.prefix(4).reduce(UInt32(0)) { ($0 << 8) | UInt32($1) }
        guard length <= maxFrameBytes else { throw WireError.frameTooLarge }
        guard data.count == 4 + Int(length) else { throw WireError.frameLengthMismatch }
        let json = data.suffix(from: 4)
        do {
            return try JSONDecoder().decode(Envelope.self, from: json)
        } catch let error as WireError {
            throw error
        } catch {
            throw WireError.malformedJSON
        }
    }

    /// Remove and return every complete frame in `buffer`. Leaves a partial
    /// frame for the next read.
    public static func drain(_ buffer: inout Data) throws -> [Envelope] {
        var envelopes: [Envelope] = []
        while buffer.count >= 4 {
            let length = buffer.prefix(4).reduce(UInt32(0)) { ($0 << 8) | UInt32($1) }
            guard length <= maxFrameBytes else { throw WireError.frameTooLarge }
            let total = 4 + Int(length)
            guard buffer.count >= total else { break }
            let frame = buffer.prefix(total)
            envelopes.append(try decode(Data(frame)))
            buffer.removeFirst(total)
        }
        return envelopes
    }
}

